package com.huawei.i2000.dvaiagentservice.business.intent;

import com.alibaba.fastjson2.JSON;
import com.huawei.bsp.log.OssLog;
import com.huawei.bsp.log.OssLogFactory;
import com.huawei.bsp.remoteservice.exception.ServiceException;
import com.huawei.bsp.roa.common.HttpContext;
import com.huawei.bsp.roa.util.restclient.RestfulParametes;
import com.huawei.bsp.roa.util.restclient.RestfulResponse;
import com.huawei.i2000.dvaiagentservice.model.QueryParam;
import com.huawei.i2000.dvaiagentservice.util.rest.RestConstant;
import com.huawei.i2000.dvaiagentservice.util.rest.RestUtil;

/**
 * 知识检索工具
 *
 * @since 2026-02-04
 */
public class KnowledgeQuery {

    private static final OssLog LOGGER = OssLogFactory.getLogger(KnowledgeQuery.class);

    public static final String RETRIEVER_KLG_URL = "/rest/naie/rag/v1/retriever";

    /**
     * 检索告警实体知识
     *
     * @param context context
     * @param queryParam queryParam
     * @return 对应的告警实体知识
     * @throws ServiceException 异常时抛出
     */
    public static KnowledgeRecommendsRsp getEntityKnowledgeRecommendsRsp(HttpContext context, QueryParam queryParam)
            throws ServiceException {
        RetrieverReq retrieverReq = RetrieverReqBuilder.getEntityRetrieverReq(queryParam);
        String param = JSON.toJSONString(retrieverReq);
        RestfulParametes restfulParametes = new RestfulParametes();
        restfulParametes.setRawData(param);
        RestfulResponse knowledgeRsp = RestUtil.sendRestRequest(context.getHttpServletRequest(),
                RestConstant.RESTFUL_METHOD_POST, RETRIEVER_KLG_URL, restfulParametes, null);
        if (retrieverReq.getRagIndexes().size() > 1 && (knowledgeRsp == null || knowledgeRsp.getStatus() != RestConstant.STATUS_OK)) {
            LOGGER.error("[entityKnowledgeSearch] query entity knowledge error index={}", queryParam.getIndexName());
            queryParam.setIndexName(IndexManagerConstants.KNOWLEDGE_ENTITY_INDEX);
            retrieverReq = RetrieverReqBuilder.getEntityRetrieverReq(queryParam);
            param = JSON.toJSONString(retrieverReq);
            restfulParametes.setRawData(param);
            RestfulResponse selfEntityKnowledgeRsp = RestUtil.sendRestRequest(context.getHttpServletRequest(),
                    RestConstant.RESTFUL_METHOD_POST, RETRIEVER_KLG_URL, restfulParametes, null);
            if (selfEntityKnowledgeRsp == null || selfEntityKnowledgeRsp.getStatus() != RestConstant.STATUS_OK) {
                LOGGER.error("[entityKnowledgeSearch] query entity knowledge error index={}", queryParam.getIndexName());
                throw new ServiceException("[entityKnowledgeSearch] query entity knowledge error");
            }
            return JSON.parseObject(selfEntityKnowledgeRsp.getResponseContent(), KnowledgeRecommendsRsp.class);
        } else {
            return JSON.parseObject(knowledgeRsp.getResponseContent(), KnowledgeRecommendsRsp.class);
        }
    }
}
```

